# ═══════════════════════════════════════════════════════════════
# run_recap_smoke.sh — RECAP Stage-1 pipeline smoke test.
#
# Assumes a LeRobot rollout dataset already exists; here it is generated by the
# built-in mock generator so the whole pipeline runs on CPU with no artifacts:
#
#   mock rollout dataset
#     -> compute_returns      (returns sidecar)
#     -> train_value          (value checkpoint)
#     -> compute_advantages   (advantages sidecar)
#     -> train_cfg --policy-backend mock   (advantage-conditioned objective)
#
# Usage:
#   bash run_recap_smoke.sh
#   RECAP_PROFILE=paper bash run_recap_smoke.sh
#   RECAP_WORK_DIR=/tmp/my_recap bash run_recap_smoke.sh
# ═══════════════════════════════════════════════════════════════
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT=${LOONGFORGE_PATH:-"$(cd "$SCRIPT_DIR/../../.." && pwd)"}
PYTHON=${PYTHON:-python3}

RECAP_WORK_DIR=${RECAP_WORK_DIR:-/tmp/recap_smoke}
RECAP_PROFILE=${RECAP_PROFILE:-baseline}   # baseline | paper
CONFIG=${CONFIG:-"$SCRIPT_DIR/configs/recap_${RECAP_PROFILE}.yaml"}

DATASET_PATH="$RECAP_WORK_DIR/mock"
VALUE_CKPT="$RECAP_WORK_DIR/value.pt"

export PYTHONPATH="$REPO_ROOT:${PYTHONPATH:-}"

echo "════════════════════════════════════════════════════════════"
echo "  RECAP Stage-1 smoke"
echo "  repo:     $REPO_ROOT"
echo "  workdir:  $RECAP_WORK_DIR"
echo "  profile:  $RECAP_PROFILE ($CONFIG)"
echo "════════════════════════════════════════════════════════════"

rm -rf "$RECAP_WORK_DIR"
mkdir -p "$RECAP_WORK_DIR"

echo "── 0. mock rollout dataset ─────────────────────────────────"
"$PYTHON" -m loongforge.embodied.recap.cli.make_mock_dataset \
    --output "$DATASET_PATH" \
    --num-tasks 2 --episodes-per-task 2 --episode-length 8

echo "── 1. compute_returns ──────────────────────────────────────"
"$PYTHON" -m loongforge.embodied.recap.cli.compute_returns \
    --dataset-path "$DATASET_PATH" --config "$CONFIG"

echo "── 2. train_value ──────────────────────────────────────────"
"$PYTHON" -m loongforge.embodied.recap.cli.train_value \
    --dataset-path "$DATASET_PATH" --output "$VALUE_CKPT" \
    --config "$CONFIG" --epochs 3

echo "── 3. compute_advantages ───────────────────────────────────"
"$PYTHON" -m loongforge.embodied.recap.cli.compute_advantages \
    --dataset-path "$DATASET_PATH" --value-checkpoint "$VALUE_CKPT" \
    --config "$CONFIG"

echo "── 4. train_cfg (mock backend) ─────────────────────────────"
"$PYTHON" -m loongforge.embodied.recap.cli.train_cfg \
    --dataset-path "$DATASET_PATH" --config "$CONFIG" \
    --policy-backend mock --steps 5

echo "════════════════════════════════════════════════════════════"
echo "  RECAP Stage-1 smoke OK"
echo "  sidecars: $DATASET_PATH/meta/returns.parquet"
echo "            $DATASET_PATH/meta/advantages.parquet"
echo "  config:   $DATASET_PATH/meta/recap_config.yaml"
echo "════════════════════════════════════════════════════════════"
